function L_cta(){const c=document.querySelector('#screenMatchs .cu-cta');if(!c)return;const m=L_me();
 c.innerHTML=m?`<button class="cu-lic cu-mine" data-lic aria-label="Voir ma licence"><span class="ph"><img alt="" src="${m.photo}"></span><span class="tx"><small>MA LICENCE · SAISON ${L_x(m.rec.sais)}</small><b>${L_x(((m.rec.nom||'').toUpperCase()+' '+(m.rec.pre||'')).trim())}</b><em>${L_x(m.rec.num)} · ${L_x(m.rec.tr||'')}</em></span><span class="go">Voir ›</span></button>`
 :`<button class="cu-lic" data-lic><span class="ic"><svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="#f6c94a" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="9" cy="11" r="2.2"/><path d="M6 16c.6-1.6 1.8-2.4 3-2.4s2.4.8 3 2.4M14.5 10h4M14.5 13.5h3"/></svg></span><span class="tx"><b>Licence de joueur</b><small>Active-la avec le code de la Fédération</small><em>Code à 4 chiffres · 4 étapes</em></span><span class="go">Obtenir ›</span></button>`}
function L_eqAuto(r){const n=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),hay=n(r.tr),ch=n((r.eg||'')+' '+r.tr);
 for(const t of Object.values(P).flat()){const nm=n(t),m=/\b(ueeso|cma|aeeci)\b/.exec(nm),core=nm.replace(/\b(ueeso|cma|aeeci)\b/g,'').replace(/\s+/g,' ').trim();if(core.length>=3&&hay.indexOf(core)>-1&&(!m||ch.indexOf(m[1])>-1))return t}return ''}
function L_eqh(){return L_chips('g_eq','eq',Object.values(P).flat().map(t=>[t]),D.eq,'g2')+(D._eqa&&D.eq?'<p class="hint">Détectée d’après ta troupe. Change-la si besoin.</p>':'')}
function L_thumb(im){try{const c=document.createElement('canvas');c.width=150;c.height=192;const x=c.getContext('2d'),r=Math.max(150/im.width,192/im.height);x.drawImage(im,(150-im.width*r)/2,(192-im.height*r)/2,im.width*r,im.height*r);return c.toDataURL('image/jpeg',.78)}catch(e){return ''}}
function L_start(){const m=L_me();if(m)return L_showMine(m);if(!L_actOK())return L_gate();L_form()}
function L_form(){ph=null;lic._ps=null;const dr=L_dGet();lic._dr=false;lic._lt=false;
 if(dr&&(dr.nom||dr.pre||dr.tr||dr.adr||dr.tel||dr.ti)){step=Math.max(0,Math.min(+dr._s||0,3));delete dr._s;D=dr;lic._dr=true}
 else{step=0;D={};const l=L_last();if(l&&l.tr){['di','tr','eg','egx','eq'].forEach(k=>{if(l[k])D[k]=l[k]});lic._lt=!!(D.di&&D.tr&&D.eg)}}
 lrender()}
/* ——— fabrication des éléments ——— */
function L_chips(id,k,items,cur,cls){return `<div class="chs ${cls||''}" id="${id}" role="radiogroup" aria-label="${L_x(k)}" tabindex="-1">${items.map(([v,l,sub])=>`<button type="button" class="chp" role="radio" aria-checked="${cur===v}" data-ck="${k}" data-cv="${L_x(v)}">${L_x(l||v)}${sub?`<small>${L_x(sub)}</small>`:''}</button>`).join('')}</div>`}
function L_trh(){if(!D.di)return '<p class="hint">Choisis d’abord ton district.</p>';const a=L_TRO().filter(t=>t.d===D.di);return a.length?L_chips('g_tr','tr',a.map(t=>[t.t]),D.tr,'g2'):'<p class="hint">Aucune troupe enregistrée pour ce district.</p>'}
function L_egh(){return L_chips('g_eg','eg',L_EGS.map(e=>[e]),D.eg,'g4')+(D.eg=='Autre'?`<input id="cf_egx" type="text" value="${L_x(D.egx||'')}" placeholder="Précise l’église" autocomplete="off" enterkeyhint="done" style="margin-top:10px">`:'')+(D._ea&&D.eg?'<p class="hint">Détectée d’après le nom de ta troupe. Change-la si besoin.</p>':'')}
function L_s1(){return '<label>District</label>'+L_chips('g_di','di',L_DIS().map(d=>[d]),D.di,'g2')+'<label>Troupe</label><div id="w_tr">'+L_trh()+'</div><label>Église</label><div id="w_eg">'+L_egh()+'</div><label>Équipe CUFLB</label><div id="w_eq">'+L_eqh()+'</div><label>Titre</label>'+L_chips('g_ti','ti',L_TIT().map(t=>[t.c,t.c,t.n]),D.ti,'g3')+'<label>Poste</label>'+L_chips('g_pos','pos',L_POS.map(p=>[p]),D.pos,'g2')+'<label>Catégorie</label>'+L_chips('g_cg','cg',L_CG.map(p=>[p]),D.cg,'g3')}
function L_recap(){const r=(l,v,s)=>`<div class="lrc"><span><em>${l}</em><b>${L_x(v||'—')}</b></span><button type="button" class="rcb" data-gs="${s}">Modifier</button></div>`;
 return '<label>Vérifie avant de générer</label><div class="rcw">'+r('Joueur',((D.nom||'').toUpperCase()+' '+(D.pre||'')).trim(),0)+r('Troupe',[D.tr,L_eg(),D.di&&'District '+D.di].filter(Boolean).join(' · '),1)+r('Équipe CUFLB',D.eq,1)+r('Titre · Poste',[D.ti,D.pos].filter(Boolean).join(' · '),1)+r('Sexe · Catégorie',[D.sx=='M'?'Masculin':D.sx=='F'?'Féminin':'',D.cg].filter(Boolean).join(' · '),0)+r('Contact',[D.tel,D.adr].filter(Boolean).join(' · '),2)+'</div>'}
const stp=()=>`<div class="stp" role="list">${ST.map((t,i)=>i<step?`<div class="dn" role="listitem button" tabindex="0" data-gs="${i}" aria-label="Revenir à l’étape ${t}"><i>✓</i><span>${t}</span></div>`:`<div class="${i==step?'on':''}" role="listitem"><i>${i+1}</i><span>${t}</span></div>`).join('')}</div>`;
function lrender(){const n=ST.length;if(step>=n)return done();
 let h=`<button class="cu-x" data-cl aria-label="Fermer">×</button><div class="lhd"><img class="lgo" src="${LOGO_LIC}" alt=""><div><img class="lwd" src="${WM}" alt="CUFLB"><small>Licence de joueur</small></div></div>${stp()}<div class="st">ÉTAPE ${step+1} / ${n}</div><h3>${L_H[step]}</h3><p class="ls">${L_SUB[step]}</p><div class="bar"><i style="width:${(step+1)/n*100}%"></i></div>`;
 if(step==0&&lic._dr)h+='<div class="dr">Brouillon repris automatiquement. <button type="button" data-rs>Recommencer</button></div>';
 if(step==1&&lic._lt)h+='<div class="dr">Troupe reprise de ta dernière licence. Touche pour changer.</div>';
 h+='<div class="fc">';
 if(step==1)h+=L_s1();
 else if(step<3){const fs=FL[step];h+=fs.map((f,i)=>`<label for="cf_${f.k}">${f.l}</label><input id="cf_${f.k}" type="${f.t||'text'}" value="${L_x(D[f.k]||f.d||'')}" autocomplete="${f.ac||'off'}"${f.im?` inputmode="${f.im}"`:''}${f.cap?` autocapitalize="${f.cap}"`:''}${f.ph?` placeholder="${L_x(f.ph)}"`:''} enterkeyhint="${i==fs.length-1?'done':'next'}"${f.t=='date'?` max="${new Date().toISOString().slice(0,10)}"`:''}>`).join('')+(step==0?L_sx():'')}
 else h+=`<label for="cf_ph">Photo d'identité</label><input id="cf_ph" type="file" accept="image/*" hidden>`+L_phb()+L_recap()+`<label class="ck"><input id="cf_ok" type="checkbox"><span>Je déclare exacts les renseignements ci-dessus et m'engage à respecter les règlements de la Fédération Ivoirienne des Flambeaux et Lumières et de la troupe à laquelle je suis affilié(e).</span></label>`;
 h+='</div>';h+=`<div class="er" id="cf_er" role="alert" aria-live="polite"></div><div class="nav">${step?'<button class="cu-btn cu-gh" data-pv>Retour</button>':''}<button class="cu-btn" data-nx>${step==n-1?'Générer ma licence':'Continuer'}</button></div>`;lic.innerHTML=h;
 const f=$('cf_ph');if(f)f.onchange=()=>{const fl=f.files&&f.files[0];fl&&L_phOpen(fl,f)};
 if(lic._err){const e=lic._err;lic._err=null;L_err(e)}
 L_dSet()}
function L_err(e){const er=$('cf_er');if(er)er.textContent=e[1];const el=$(e[0])||$('cf_'+e[0]);if(el){el.classList&&el.classList.add('bad');el.setAttribute('aria-invalid','true');el.scrollIntoView&&el.scrollIntoView({block:'center',behavior:'smooth'});el.focus&&el.focus({preventScroll:true})}}
/* V131 — « Ajuster ma photo » : cadrage, zoom et effets de la photo d'identité (sans miroir, sans partage, sans N&B) */
const PA_W=480,PA_H=616;
function L_phb(){const cam='<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 8.5A2.5 2.5 0 0 1 6.5 6h1.2l1.3-2h6l1.3 2h1.2A2.5 2.5 0 0 1 20 8.5v9a2.5 2.5 0 0 1-2.5 2.5h-11A2.5 2.5 0 0 1 4 17.5z"/><circle cx="12" cy="13" r="3.6"/></svg>';
 if(!ph)return '<button type="button" class="phb phadd" id="cf_phb" data-phc><span class="phi">'+cam+'</span><b>Ajouter ma photo</b><small>Galerie ou appareil photo, puis ajuste-la</small></button>';
 return '<div class="phb phok" id="cf_phb" tabindex="-1"><img class="phpv" alt="Aperçu de ta photo" src="'+ph.src+'"><div class="pht"><b>Photo ajoutée</b><small>Elle apparaîtra sur ta licence.</small><div class="pha"><button type="button" class="phe" data-phe>Ajuster</button><button type="button" class="phe" data-phc>Changer la photo</button></div></div></div>'}
function L_phLoad(file,inp,ok,ko){const r=new FileReader();
 r.onerror=()=>{if(inp)inp.value='';ko()};
 r.onload=()=>{if(inp)inp.value='';const im=new Image();im.onerror=ko;
  im.onload=()=>{if(!im.width||!im.height)return ko();const k=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));c.getContext('2d').drawImage(im,0,0,c.width,c.height);ok(c)};
  im.src=r.result};
 r.readAsDataURL(file)}
function L_phOpen(file,inp){L_phLoad(file,inp,c=>L_paShow({src:c,z:1,ox:0,oy:0,f:'o'}),()=>L_err(['cf_phb','Cette photo est illisible. Choisis-en une autre.']))}
let pa=null;
function L_paDraw(c,s){const x=c.getContext('2d'),im=s.src,b=Math.max(PA_W/im.width,PA_H/im.height),k=b*s.z,w=im.width*k,h=im.height*k,mx=Math.max(0,(w-PA_W)/2),my=Math.max(0,(h-PA_H)/2);
 s.ox=Math.max(-mx,Math.min(mx,s.ox));s.oy=Math.max(-my,Math.min(my,s.oy));
 x.fillStyle='#fff';x.fillRect(0,0,PA_W,PA_H);x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';
 x.drawImage(im,PA_W/2+s.ox-w/2,PA_H/2+s.oy-h/2,w,h);
 if(s.f=='e'||s.f=='c'){const d=x.getImageData(0,0,PA_W,PA_H),p=d.data,n=p.length,ec=s.f=='e',t=ec?1.2:1.08;
  for(let i=0;i<n;i+=4){let r=p[i],g=p[i+1],bl=p[i+2];
   if(ec){r=(r-128)*1.1+140;g=(g-128)*1.1+140;bl=(bl-128)*1.1+140}else{r=r*1.08+5;g=g*1.02+1;bl=bl*.88-3}
   const l=.299*r+.587*g+.114*bl;p[i]=l+(r-l)*t;p[i+1]=l+(g-l)*t;p[i+2]=l+(bl-l)*t}
  x.putImageData(d,0,0)}}
function L_paSync(){const s=pa&&pa._s;if(!s)return;L_paDraw(pa.querySelector('#paC'),s);const R=pa.querySelector('#paR');R.value=s.z;R.style.setProperty('--p',((s.z-1)/3*100)+'%');
 pa.querySelectorAll('[data-paf]').forEach(b=>b.setAttribute('aria-checked',b.dataset.paf===s.f))}
function L_paBuild(){pa=document.createElement('div');pa.id='cuPh';pa.setAttribute('role','dialog');pa.setAttribute('aria-modal','true');pa.setAttribute('aria-labelledby','paT');pa.tabIndex=-1;
 pa.innerHTML='<div class="pa-top"><h2 id="paT">Ajuster ma photo</h2><button type="button" class="pa-x" data-pax aria-label="Fermer sans enregistrer">×</button></div>'
 +'<div class="pa-stage"><div class="pa-wrap" id="paW"><canvas id="paC" width="'+PA_W+'" height="'+PA_H+'" role="img" aria-label="Aperçu de ta photo dans le cadre"></canvas></div></div>'
 +'<div class="pa-zoom"><button type="button" class="pa-rb" data-paz="-1" aria-label="Zoom arrière">−</button><input type="range" id="paR" min="1" max="4" step="0.01" value="1" aria-label="Zoom"><button type="button" class="pa-rb" data-paz="1" aria-label="Zoom avant">+</button></div>'
 +'<div class="pa-fl" role="radiogroup" aria-label="Effet de la photo"><button type="button" role="radio" aria-checked="true" data-paf="o">Original</button><button type="button" role="radio" aria-checked="false" data-paf="e">Éclat</button><button type="button" role="radio" aria-checked="false" data-paf="c">Chaud</button></div>'
 +'<button type="button" class="pa-re" data-par>Recentrer</button>'
 +'<p class="pa-h">Glisse pour déplacer · pince ou utilise le curseur pour zoomer</p><p class="pa-er" id="paE" role="alert" aria-live="polite"></p>'
 +'<button type="button" class="pa-ok" data-paok>Enregistrer</button>'
 +'<button type="button" class="pa-ch" data-pach>Changer la photo</button><input type="file" id="cuPhF" accept="image/*" hidden>';
 document.body.appendChild(pa);
 const w=pa.querySelector('#paW'),R=pa.querySelector('#paR'),pts=new Map(),cl=(v,a,b)=>Math.max(a,Math.min(b,v));let d0=1,z0=1,raf=0;
 const req=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;L_paSync()})};
 const dist=()=>{const a=[...pts.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)||1};
 w.addEventListener('pointerdown',e=>{if(!pa._s)return;try{w.setPointerCapture(e.pointerId)}catch(_){}pts.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pts.size==2){d0=dist();z0=pa._s.z}});
 w.addEventListener('pointermove',e=>{const p=pts.get(e.pointerId),s=pa._s;if(!p||!s)return;const k=PA_W/(w.getBoundingClientRect().width||PA_W);
  if(pts.size==1){s.ox+=(e.clientX-p.x)*k;s.oy+=(e.clientY-p.y)*k}
  p.x=e.clientX;p.y=e.clientY;
  if(pts.size==2)s.z=cl(z0*dist()/d0,1,4);
  req()});
 ['pointerup','pointercancel','lostpointercapture'].forEach(n=>w.addEventListener(n,e=>{pts.delete(e.pointerId)}));
 w.addEventListener('wheel',e=>{if(!pa._s)return;e.preventDefault();pa._s.z=cl(pa._s.z*(e.deltaY<0?1.08:1/1.08),1,4);req()},{passive:false});
 R.addEventListener('input',()=>{if(!pa._s)return;pa._s.z=cl(+R.value,1,4);req()});
 pa.addEventListener('click',e=>{const b=e.target.closest('button'),s=pa._s;if(!b||!s)return;
  if(b.hasAttribute('data-pax'))L_paHide();
  else if(b.dataset.paz){s.z=cl(s.z+(+b.dataset.paz)*.2,1,4);req()}
  else if(b.dataset.paf){s.f=b.dataset.paf;req()}
  else if(b.hasAttribute('data-par')){s.z=1;s.ox=0;s.oy=0;req()}
  else if(b.hasAttribute('data-paok'))L_paSave();
  else if(b.hasAttribute('data-pach'))pa.querySelector('#cuPhF').click()});
 pa.querySelector('#cuPhF').addEventListener('change',e=>{const f=e.target.files&&e.target.files[0];if(!f)return;const er=pa.querySelector('#paE');
  L_phLoad(f,e.target,c=>{er.textContent='';const o=pa._s;pa._s={src:c,z:1,ox:0,oy:0,f:o?o.f:'o'};req()},()=>{er.textContent='Cette photo est illisible. Choisis-en une autre.'})});
 document.addEventListener('keydown',e=>{if(e.key=='Escape'&&pa&&pa.classList.contains('on')){e.preventDefault();L_paHide()}})}
function L_paShow(s){if(!pa)L_paBuild();pa._s=s;pa.querySelector('#paE').textContent='';pa.classList.add('on');L_paSync();pa.scrollTop=0;try{pa.focus({preventScroll:true})}catch(e){}}
function L_paHide(){if(pa)pa.classList.remove('on')}
function L_paSave(){const s=pa&&pa._s;if(!s)return;const c=document.createElement('canvas');c.width=PA_W;c.height=PA_H;L_paDraw(c,s);const im=new Image();
 im.onload=()=>{ph=im;lic._ps={...s};L_paHide();collect();lrender();const b=$('cf_phb');b&&b.scrollIntoView&&b.scrollIntoView({block:'nearest'})};
 im.onerror=L_paHide;im.src=c.toDataURL('image/jpeg',.92)}
document.addEventListener('click',e=>{const c=e.target.closest&&e.target.closest('#cuLic [data-phc]');if(c){const f=$('cf_ph');f&&f.click();return}
 const b=e.target.closest&&e.target.closest('#cuLic [data-phe]');if(b&&ph)L_paShow(lic._ps?{...lic._ps}:{src:ph,z:1,ox:0,oy:0,f:'o'})});
function collect(){if(step==1){const x=$('cf_egx');if(x)D.egx=x.value.trim()}else if(step<3&&FL[step])FL[step].forEach(f=>{const el=$('cf_'+f.k);if(el)D[f.k]=el.value.trim()});L_dSet()}
function L_val(s){
 if(s==0){for(const f of FL[0])if(!D[f.k])return [f.k,f.l+' obligatoire.'];if(D.dn){const t=new Date(D.dn);if(isNaN(t)||t>new Date()||t.getFullYear()<1930)return ['dn','Date de naissance invalide.']}if(!D.sx)return ['g_sx','Choisis ton sexe.']}
 if(s==1){if(!D.di)return ['g_di','Choisis ton district.'];if(!D.tr)return ['g_tr','Choisis ta troupe.'];if(!D.eg)return ['g_eg','Choisis ton église.'];if(D.eg=='Autre'&&!(D.egx||'').trim())return ['cf_egx','Précise ton église.'];if(!D.eq)return ['g_eq','Choisis ton équipe CUFLB.'];if(!D.ti)return ['g_ti','Choisis ton titre.'];if(!D.pos)return ['g_pos','Choisis ton poste.'];if(!D.cg)return ['g_cg','Choisis ta catégorie.']}
 if(s==2){for(const f of FL[2])if(!D[f.k]&&!f.opt)return [f.k,f.l+' obligatoire.'];if(D.tel.replace(/\D/g,'').length<8)return ['tel','Numéro de téléphone invalide.'];if(D.mail&&!/^\S+@\S+\.\S+$/.test(D.mail))return ['mail','E-mail invalide.']}
 if(s==3){if(!ph)return ['cf_phb','Ajoute ta photo d\'identité.'];if(!$('cf_ok').checked)return ['cf_ok','Coche l\'engagement pour continuer.']}
 return null}
function nextStep(){collect();let e=L_val(step);
 if(!e&&step==3){for(let s=0;s<3;s++){const v=L_val(s);if(v){step=s;lic._err=v;lrender();return}}}
 if(e){L_err(e);return}
 step++;lrender();lic.scrollTop=0}
function L_go(i){collect();step=i;lrender();lic.scrollTop=0}
function L_pick(k,v){
 if(k=='di'){if(D.di!==v){D.di=v;if(!L_TRO().some(t=>t.d===v&&t.t===D.tr)){D.tr='';if(D._ea){D.eg='';D._ea=0}}}}
 else if(k=='tr'){D.tr=v;const a=L_egOf(v);if(a){D.eg=a;D._ea=1}else if(D._ea){D.eg='';D._ea=0}}
 else if(k=='eg'){D.eg=v;D._ea=0}
 else{D[k]=v;if(k=='eq')D._eqa=0}
 if((k=='di'||k=='tr'||k=='eg')&&(!D.eq||D._eqa)){const a=L_eqAuto({tr:D.tr,eg:L_eg()});if(a){D.eq=a;D._eqa=1}else if(D._eqa){D.eq='';D._eqa=0}}
 lic._lt=false;if(k=='di'||k=='tr'||k=='eg'){const w1=$('w_tr'),w2=$('w_eg');if(w1)w1.innerHTML=L_trh();if(w2)w2.innerHTML=L_egh()}if(k=='di'||k=='tr'||k=='eg'||k=='eq'){const w3=$('w_eq');if(w3)w3.innerHTML=L_eqh()}
 lic.querySelectorAll('[data-ck]').forEach(b=>b.setAttribute('aria-checked',D[b.dataset.ck]===b.dataset.cv));
 const er=$('cf_er');if(er)er.textContent='';const hn=lic.querySelector('.dr');if(hn&&!lic._dr)hn.remove();
 if(k=='eg'&&v=='Autre'){const x=$('cf_egx');x&&x.focus()}
 L_dSet()}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('#cuLic [data-ck]');if(b){L_pick(b.dataset.ck,b.dataset.cv);return}
 const g=e.target.closest&&e.target.closest('#cuLic [data-gs]');if(g){L_go(+g.dataset.gs);return}
 if(e.target.closest&&e.target.closest('#cuLic [data-rs]')){L_dClr();D={};ph=null;lic._ps=null;step=0;lic._dr=false;lrender()}});
document.addEventListener('keydown',e=>{if(!lic.classList.contains('on'))return;
 const g=e.target.closest&&e.target.closest('#cuLic [data-gs]');if(g&&g.tagName=='DIV'&&(e.key=='Enter'||e.key==' ')){e.preventDefault();L_go(+g.dataset.gs);return}
 if(e.key=='Enter'&&e.target.matches&&e.target.matches('#cuLic input:not([type=file]):not([type=checkbox])')){e.preventDefault();const ins=[...lic.querySelectorAll('input:not([type=file]):not([type=checkbox])')],i=ins.indexOf(e.target);if(i<ins.length-1)ins[i+1].focus();else nextStep()}});
